/* global test expect */
import { DateTime, Interval, Settings } from "/luxon/src/luxon";
import Helpers from "/luxon/test/helpers";

const withThrowOnInvalid = Helpers.setUnset("throwOnInvalid");

test("Interval.fromISO works with Settings.throwOnInvalid", () => {
  withThrowOnInvalid(true, () => {
    expect(() => Interval.fromISO("P1Y/2016-01-01")).not.toThrow();
    expect(() => Interval.fromISO("2016-01-01/P1Y")).not.toThrow();
    expect(() => Interval.fromISO("2016-01-01/2016-12-31")).not.toThrow();
    expect(() => Interval.fromISO("blah/blah")).toThrow();
  });
});

test("DateTime#plus works across the 100 barrier when passing through February", () => {
  const d = DateTime.fromISO("0099-12-31").plus({ days: 60 });
  expect(d.year).toBe(100);
  expect(d.month).toBe(3);
  expect(d.day).toBe(1);
  const e = DateTime.fromISO("0099-12-31").plus({ days: 61 });
  expect(e.year).toBe(100);
  expect(e.month).toBe(3);
  expect(e.day).toBe(2);
  const f = DateTime.fromISO("0100-03-01").minus({ days: 60 });
  expect(f.year).toBe(99);
  expect(f.month).toBe(12);
  expect(f.day).toBe(31);
});

test("DateTime#isInDST() returns true for 1974 whole year in USA- from January 6th to October 27th", () => {
  const jan = DateTime.fromISO("1974-01-06T00:00:00", { zone: "America/New_York" });
  expect(jan.isInDST).toBe(true);
  const oct = DateTime.fromISO("1974-10-27T00:00:00", { zone: "America/New_York" });
  expect(oct.isInDST).toBe(true);
  for (let i = 0; i < 295; i++) {
    const d = DateTime.fromISO("1974-01-06T12:00:00", { zone: "America/New_York" }).plus({ days: i });
    expect(d.isInDST).toBe(true);
  }
  expect(DateTime.fromISO("1974-01-05T12:00:00", { zone: "America/New_York" }).isInDST).toBe(false);
  expect(DateTime.fromISO("1974-10-28T12:00:00", { zone: "America/New_York" }).isInDST).toBe(false);
});
EOF
